		assert(region_archive_set_chunk(&ra,1,0,&sc,&plain_te,&plain_ents));
		assert(region_archive_sync(&ra));
		region_archive_journal_stats(rj_after);
		assert(rj_after[10]==rj_before[10]+1 && rj_after[11]==rj_before[11]+1
			   && "a chunk with nothing foreign must take the short path");
		struct buffer second=read_file(path);
