/* The gzip header's OS byte (offset 9) is pinned to 0, as Java's
 * GZIPOutputStream wrote it (nbt_loading.c __compress). Saves written before
 * that carry the host zlib's OS_CODE: 0x0a (Win32) or 0x03 (Unix/devkitPPC).
 * Such a file must still load, a no-op save must leave it untouched (the skip
 * compares uncompressed NBT, never the compressed header), and once a real
 * edit rewrites it the result is the OS-0 golden with no further rewrites. */
static void legacy_os_byte_level(const char* dir) {
	static const uint8_t legacy[]={0x0a,0x03};
	char lp[256]; snprintf(lp,sizeof(lp),"%s/level.dat",dir);
	struct buffer level=native_file("world/level.dat"),edited=native_file("edited/level.dat");
	assert(level.len>10 && level.data[0]==0x1f && level.data[1]==0x8b && level.data[9]==0);
	assert(edited.len>10 && edited.data[9]==0);
	for(unsigned k=0;k<sizeof(legacy);k++) {
		struct buffer old=BUFFER_INIT; bytes(&old,level.data,level.len); old.data[9]=legacy[k];
		write_file(lp,&old);
		string_t world; string_init_set_str(world,dir);
		struct level_archive la; assert(level_archive_create(&la,world));
		struct item_data items[INVENTORY_SIZE]={0}; struct inventory inv={.items=items,.capacity=INVENTORY_SIZE};
		assert(level_archive_read_inventory(&la,&inv));
		assert(items[INVENTORY_SLOT_HOTBAR].id==5 && items[INVENTORY_SLOT_HOTBAR].count==8);
		/* No-op: not re-dirtied, the legacy header byte survives. */
		assert(level_archive_write_inventory(&la,&inv)); assert(level_archive_save(&la));
		struct buffer actual=read_file(lp); same(&old,&actual); buffer_free(&actual);
		/* A real edit rewrites exactly the OS-0 golden... */
		items[INVENTORY_SLOT_HOTBAR].count--;
		assert(level_archive_write_inventory(&la,&inv)); assert(level_archive_save(&la));
		actual=read_file(lp); same(&edited,&actual); buffer_free(&actual);
		/* ...after which a no-op save is again a no-op (no rewrite loop). */
		assert(level_archive_write_inventory(&la,&inv)); assert(level_archive_save(&la));
		actual=read_file(lp); same(&edited,&actual); buffer_free(&actual);
		level_archive_discard(&la);
		/* Reload the rewritten file: it parses and holds the edit. */
		assert(level_archive_create(&la,world));
		struct item_data again[INVENTORY_SIZE]={0}; struct inventory inv2={.items=again,.capacity=INVENTORY_SIZE};
		assert(level_archive_read_inventory(&la,&inv2)); assert(again[INVENTORY_SLOT_HOTBAR].count==7);
		level_archive_discard(&la); string_clear(world); buffer_free(&old);
	}
	buffer_free(&level); buffer_free(&edited);
	puts("legacy gzip OS byte 0x0a/0x03: loads, no-op save untouched, edit writes OS-0 golden, no rewrite loop PASS");
}
