		assert(region_archive_get_chunk(&ra,0,0,&sc,&te,&entities));
		assert(te.n_chest==1 && (te.chests[0].items[0].count==8 || te.chests[0].items[0].count==7));
		assert(region_archive_destroy(&ra));
		tile_entities_parse_free(&te);chunk_entities_free(&entities);
		mem2_free(sc.ids);mem2_free(sc.metadata);mem2_free(sc.lighting_sky);mem2_free(sc.lighting_torch);mem2_free(sc.heightmap);
		struct buffer recovered=read_file(rp);
