static void resource_refusal(const char* dir) {
	string_t world; string_init_set_str(world,dir);
	struct level_archive la;
	assert(level_archive_create_new(&la,world,42,(vec3){0,70,0}));
	la.modified=true; assert(level_archive_save(&la)); level_archive_discard(&la);
	char path[256], backup[256], candidate[256];
	snprintf(path,sizeof(path),"%s/level.dat",dir);
	snprintf(backup,sizeof(backup),"%s/level.dat_old",dir);
	struct buffer old=read_file(path); write_file(backup,&old);
	snprintf(candidate,sizeof(candidate),"%s/level.dat_new",dir);write_file(candidate,&old);
	struct buffer raw=BUFFER_INIT; name(&raw,TAG_COMPOUND,"");
	array(&raw,"Oversized",8u*1024u*1024u-21u); byte(&raw,0);
	/* Valid gzip/NBT, larger than the resource budget, not corruption. */
	uLongf length=compressBound((uLong)raw.len);
	struct buffer compressed=BUFFER_INIT;
	assert(!buffer_reserve(&compressed,length));
	assert(compress2(compressed.data,&length,raw.data,(uLong)raw.len,1)==Z_OK);
	compressed.len=length; write_file(path,&compressed);
	assert(!level_archive_create(&la,world)); assert(errno==NBT_EREFUSED);
	struct buffer after=read_file(path); same(&compressed,&after); buffer_free(&after);
	after=read_file(backup); same(&old,&after); buffer_free(&after);
	after=read_file(candidate);same(&old,&after);buffer_free(&after);
	buffer_free(&raw); buffer_free(&compressed); buffer_free(&old); string_clear(world);
	puts("over-budget primary: NBT_EREFUSED, primary and backup byte-identical PASS");
}
static void saturation(void) {
	unsigned before=item_nbt_exhaustions();
	unsigned initial=item_nbt_templates();
	struct buffer raw=BUFFER_INIT; name(&raw,TAG_COMPOUND,"");
	name(&raw,1,"Slot"); byte(&raw,0); name(&raw,2,"id"); byte(&raw,0); byte(&raw,5);
	name(&raw,1,"Count"); byte(&raw,8); name(&raw,2,"Damage"); byte(&raw,0); byte(&raw,0);
	name(&raw,3,"Distinct"); size_t at=raw.len; u32(&raw,0); byte(&raw,0);
	struct item_data first={0};
	for(unsigned k=0;k<=ITEM_NBT_RECORDS-initial;k++) {
		raw.data[at+2]=(uint8_t)(k>>8); raw.data[at+3]=(uint8_t)k;
		nbt_node* n=nbt_parse(raw.data,raw.len); assert(n);
		struct item_data it={.id=5,.count=8}; item_nbt_capture(n,&it); nbt_free(n);
		if(!k) first=it;
		if(k<ITEM_NBT_RECORDS-initial) {
			assert(!item_data_pinned(&it) && item_nbt_templates()==initial+k+1);
		} else assert(item_data_pinned(&it));
	}
	assert(item_nbt_templates()==254 && item_nbt_exhaustions()==before+1);
	before=item_nbt_exhaustions(); raw.data[at+2]=raw.data[at+3]=0;
	nbt_node* n=nbt_parse(raw.data,raw.len); assert(n);
	struct item_data it={.id=5,.count=8}; item_nbt_capture(n,&it); nbt_free(n);
	assert(it.nbt_record==first.nbt_record && !item_data_pinned(&it));
	assert(item_nbt_exhaustions()==before);
	struct item_data canonical={.id=5,.count=8,.durability=258};nbt_node emitted;
	assert(item_nbt_emit(&emitted,&canonical,0));item_nbt_capture(&emitted,&canonical);
	assert(canonical.nbt_record==0 && item_nbt_exhaustions()==before);
	free(emitted.payload.tag_byte_array.data);
	buffer_free(&raw);
	puts("254 distinct templates: saturation pins, existing template usable PASS");
}

